#nullable enable // autogenerated

using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.autotrap_Evoke)]
    public class Autotrap_Evoke : ContraptionEvokeBehaviour
    {
        public Autotrap_Evoke(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Evoke(Entity entity)
        {
            base.Evoke(entity);
            entity.SetEvoked(true);
            entity.PlaySound(VanillaSoundID.teslaAttack);
        }
    }
}
